1	/**
2	 * RVF Migration Utility — bidirectional migration between RVF and legacy
3	 * formats (JSON files, sql.js / better-sqlite3 databases).
4	 * @module @claude-flow/memory/rvf-migration
5	 */
6	import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
7	import { existsSync } from 'node:fs';
8	import { dirname, resolve } from 'node:path';
9	import { RvfBackend } from './rvf-backend.js';
10	import type { MemoryEntry, MemoryType, AccessLevel } from './types.js';
11	import { generateMemoryId } from './types.js';
12	
13	/** Options for controlling the migration process. */
14	export interface RvfMigrationOptions {
15	  verbose?: boolean;
16	  /** Entries per batch (default 500). */
17	  batchSize?: number;
18	  /** Embedding dimensions for target RVF file (default 1536). */
19	  dimensions?: number;
20	  onProgress?: (progress: { current: number; total: number; phase: string }) => void;
21	}
22	
23	/** Result returned after a migration completes. */
24	export interface RvfMigrationResult {
25	  success: boolean;
26	  entriesMigrated: number;
27	  sourceFormat: string;
28	  targetFormat: string;
29	  durationMs: number;
30	  errors: string[];
31	}
32	
33	// -- Internal helpers -------------------------------------------------------
34	
35	function fillDefaults(raw: Record<string, unknown>): MemoryEntry {
36	  const now = Date.now();
37	  return {
38	    id: (raw.id as string) ?? generateMemoryId(),
39	    key: (raw.key as string) ?? '',
40	    content: (raw.content as string) ?? '',
41	    type: (raw.type as MemoryType) ?? 'semantic',
42	    namespace: (raw.namespace as string) ?? 'default',
43	    tags: (raw.tags as string[]) ?? [],
44	    metadata: (raw.metadata as Record<string, unknown>) ?? {},
45	    ownerId: raw.ownerId as string | undefined,
46	    accessLevel: (raw.accessLevel as AccessLevel) ?? 'private',
47	    createdAt: (raw.createdAt as number) ?? now,
48	    updatedAt: (raw.updatedAt as number) ?? now,
49	    expiresAt: raw.expiresAt as number | undefined,
50	    version: (raw.version as number) ?? 1,
51	    references: (raw.references as string[]) ?? [],
52	    accessCount: (raw.accessCount as number) ?? 0,
53	    lastAccessedAt: (raw.lastAccessedAt as number) ?? now,
54	    embedding: deserializeEmbedding(raw.embedding),
55	  };
56	}
57	
58	function deserializeEmbedding(value: unknown): Float32Array | undefined {
59	  if (!value) return undefined;
60	  if (value instanceof Float32Array) return value;
61	  if (value instanceof Buffer || value instanceof Uint8Array) {
62	    if (value.byteLength === 0) return undefined;
63	    const out = new Float32Array(value.byteLength / 4);
64	    const view = new DataView(value.buffer, value.byteOffset, value.byteLength);
65	    for (let i = 0; i < out.length; i++) out[i] = view.getFloat32(i * 4, true);
66	    return out;
67	  }
68	  if (Array.isArray(value)) return new Float32Array(value as number[]);
69	  return undefined;
70	}
71	
72	function serializeForJson(entry: MemoryEntry): Record<string, unknown> {
73	  return { ...entry, embedding: entry.embedding ? Array.from(entry.embedding) : undefined };
74	}
75	
76	function validateMigrationPath(p: string): void {
77	  if (!p || typeof p !== 'string') throw new Error('Path must be a non-empty string');
78	  if (p.includes('\0')) throw new Error('Path contains null bytes');
79	}
80	
81	async function ensureDir(filePath: string): Promise<void> {
82	  validateMigrationPath(filePath);
83	  const dir = dirname(resolve(filePath));
84	  if (!existsSync(dir)) await mkdir(dir, { recursive: true });
85	}
86	
87	async function atomicWrite(targetPath: string, data: string | Buffer): Promise<void> {
88	  validateMigrationPath(targetPath);
89	  const abs = resolve(targetPath);
90	  const tmp = abs + '.tmp.' + Date.now();
91	  await ensureDir(abs);
92	  await writeFile(tmp, data, typeof data === 'string' ? 'utf-8' : undefined);
93	  await rename(tmp, abs);
94	}
95	
96	function mkResult(
97	  success: boolean, entriesMigrated: number, sourceFormat: string,
98	  targetFormat: string, startMs: number, errors: string[],
99	): RvfMigrationResult {
100	  return { success, entriesMigrated, sourceFormat, targetFormat, durationMs: Date.now() - startMs, errors };
101	}
102	
103	function normalizeSqliteRow(row: Record<string, unknown>): Record<string, unknown> {
104	  const out: Record<string, unknown> = { ...row };
105	  for (const col of ['tags', 'metadata', 'references'] as const) {
106	    if (typeof out[col] === 'string') {
107	      try { out[col] = JSON.parse(out[col] as string); } catch { out[col] = col === 'metadata' ? {} : []; }
108	    }
109	  }
110	  return out;
111	}
112	
113	// -- SQLite reader (better-sqlite3 first, then sql.js) ----------------------
114	
115	interface SqliteRow { [key: string]: unknown }
116	
117	async function readSqliteRows(dbPath: string): Promise<SqliteRow[]> {
118	  // Attempt better-sqlite3
119	  try {
120	    const mod = await import('better-sqlite3' as string);
121	    const Database = mod.default ?? mod;
122	    const db = new Database(dbPath, { readonly: true });
123	    try { return db.prepare('SELECT * FROM memory_entries').all() as SqliteRow[]; }
124	    finally { db.close(); }
125	  } catch { /* unavailable */ }
126	  // Attempt sql.js
127	  try {
128	    const mod = await import('sql.js' as string);
129	    const SQL = await (mod.default ?? mod)();
130	    const db = new SQL.Database(await readFile(dbPath));
131	    try {
132	      const stmt = db.prepare('SELECT * FROM memory_entries');
133	      const rows: SqliteRow[] = [];
134	      while (stmt.step()) rows.push(stmt.getAsObject() as SqliteRow);
135	      stmt.free();
136	      return rows;
137	    } finally { db.close(); }
138	  } catch { /* unavailable */ }
139	  throw new Error('Cannot read SQLite: install better-sqlite3 or sql.js');
140	}
141	
142	// -- Batch migration helper -------------------------------------------------
143	
144	async function migrateBatches(
145	  items: Record<string, unknown>[],
146	  rvfPath: string,
147	  options: RvfMigrationOptions,
148	  normalize?: (r: Record<string, unknown>) => Record<string, unknown>,
149	): Promise<{ migrated: number; errors: string[] }> {
150	  const batchSize = options.batchSize ?? 500;
151	  const dimensions = options.dimensions ?? 1536;
152	  const backend = new RvfBackend({ databasePath: rvfPath, dimensions, verbose: options.verbose });
153	  await backend.initialize();
154	  let migrated = 0;
155	  const errors: string[] = [];
156	  try {
157	    for (let i = 0; i < items.length; i += batchSize) {
158	      const batch = items.slice(i, i + batchSize);
159	      const entries: MemoryEntry[] = [];
160	      for (const item of batch) {
161	        try {
162	          entries.push(fillDefaults(normalize ? normalize(item) : item));
163	        } catch (e) { errors.push(`Entry ${item.id ?? i}: ${(e as Error).message}`); }
164	      }
165	      if (entries.length > 0) { await backend.bulkInsert(entries); migrated += entries.length; }
166	      options.onProgress?.({ current: Math.min(i + batchSize, items.length), total: items.length, phase: 'migrating' });
167	    }
168	  } finally { await backend.shutdown(); }
169	  return { migrated, errors };
170	}
171	
172	/**
173	 * Bidirectional migration utility between RVF and legacy memory formats.
174	 *
175	 * All methods are static — no instantiation required.
176	 */
177	export class RvfMigrator {
178	  /** Migrate a JSON memory file to RVF format. */
179	  static async fromJsonFile(
180	    jsonPath: string, rvfPath: string, options: RvfMigrationOptions = {},
181	  ): Promise<RvfMigrationResult> {
182	    const start = Date.now();
183	    const raw = await readFile(jsonPath, 'utf-8');
184	    let parsed: unknown;
185	    try { parsed = JSON.parse(raw); }
186	    catch (e) { return mkResult(false, 0, 'json', 'rvf', start, [`Invalid JSON: ${(e as Error).message}`]); }
187	    const items = Array.isArray(parsed) ? parsed : [parsed as Record<string, unknown>];
188	    const { migrated, errors } = await migrateBatches(items, rvfPath, options);
189	    if (options.verbose) console.log(`[RvfMigrator] Migrated ${migrated} entries from JSON to RVF`);
190	    return mkResult(errors.length === 0, migrated, 'json', 'rvf', start, errors);
191	  }
192	
193	  /** Migrate a SQLite (better-sqlite3 / sql.js) database to RVF. */
194	  static async fromSqlite(
195	    dbPath: string, rvfPath: string, options: RvfMigrationOptions = {},
196	  ): Promise<RvfMigrationResult> {
197	    const start = Date.now();
198	    let rows: SqliteRow[];
199	    try { rows = await readSqliteRows(dbPath); }
200	    catch (e) { return mkResult(false, 0, 'sqlite', 'rvf', start, [(e as Error).message]); }
201	    options.onProgress?.({ current: 0, total: rows.length, phase: 'reading' });
202	    const { migrated, errors } = await migrateBatches(rows, rvfPath, options, normalizeSqliteRow);
203	    if (options.verbose) console.log(`[RvfMigrator] Migrated ${migrated} entries from SQLite to RVF`);
204	    return mkResult(errors.length === 0, migrated, 'sqlite', 'rvf', start, errors);
205	  }
206	
207	  /** Export an RVF file back to a JSON array (backward compatibility). */
208	  static async toJsonFile(rvfPath: string, jsonPath: string): Promise<RvfMigrationResult> {
209	    const start = Date.now();
210	    const backend = new RvfBackend({ databasePath: rvfPath });
211	    await backend.initialize();
212	    let entries: MemoryEntry[];
213	    try { entries = await backend.query({ type: 'hybrid', limit: Number.MAX_SAFE_INTEGER }); }
214	    finally { await backend.shutdown(); }
215	    const warnings: string[] = [];
216	    if (entries.length === 0) warnings.push('Source RVF file contained no entries');
217	    await atomicWrite(jsonPath, JSON.stringify(entries.map(serializeForJson), null, 2));
218	    return mkResult(true, entries.length, 'rvf', 'json', start, warnings);
219	  }
220	
221	  /**
222	   * Detect file format by magic bytes.
223	   * - RVF\0 (0x52 0x56 0x46 0x00) -> 'rvf'
224	   * - SQLi  (0x53 0x51 0x4C 0x69) -> 'sqlite'
225	   * - Leading [ or {              -> 'json'
226	   */
227	  static async detectFormat(filePath: string): Promise<'rvf' | 'json' | 'sqlite' | 'unknown'> {
228	    if (!existsSync(filePath)) return 'unknown';
229	    const fd = await import('node:fs').then(m => m.promises.open(filePath, 'r'));
230	    try {
231	      const buf = Buffer.alloc(16);
232	      await fd.read(buf, 0, 16, 0);
233	      if (buf[0] === 0x52 && buf[1] === 0x56 && buf[2] === 0x46 && buf[3] === 0x00) return 'rvf';
234	      if (buf[0] === 0x53 && buf[1] === 0x51 && buf[2] === 0x4C && buf[3] === 0x69) return 'sqlite';
235	      const head = buf.toString('utf-8').trimStart();
236	      if (head.startsWith('[') || head.startsWith('{')) return 'json';
237	      return 'unknown';
238	    } finally { await fd.close(); }
239	  }
240	
241	  /** Auto-detect source format and migrate to RVF. */
242	  static async autoMigrate(
243	    sourcePath: string, targetRvfPath: string, options: RvfMigrationOptions = {},
244	  ): Promise<RvfMigrationResult> {
245	    const format = await RvfMigrator.detectFormat(sourcePath);
246	    if (options.verbose) console.log(`[RvfMigrator] Detected source format: ${format}`);
247	    switch (format) {
248	      case 'json':   return RvfMigrator.fromJsonFile(sourcePath, targetRvfPath, options);
249	      case 'sqlite': return RvfMigrator.fromSqlite(sourcePath, targetRvfPath, options);
250	      case 'rvf':    return { success: true, entriesMigrated: 0, sourceFormat: 'rvf', targetFormat: 'rvf', durationMs: 0, errors: [] };
251	      default:       return { success: false, entriesMigrated: 0, sourceFormat: 'unknown', targetFormat: 'rvf', durationMs: 0, errors: [`Unrecognized format: ${sourcePath}`] };
252	    }
253	  }
254	}
