29	/**
30	 * Available database provider types.
31	 *
32	 * ADR-125 Phase 2 added `'hybrid'` and `'agentdb'` so the package can deliver
33	 * ADR-009's "HybridBackend by default" promise through `createDatabase`.
34	 */
35	export type DatabaseProvider =
36	  | 'better-sqlite3'
37	  | 'sql.js'
38	  | 'json'
39	  | 'rvf'
40	  | 'hybrid'
41	  | 'agentdb'
42	  | 'auto';
43	
44	/**
45	 * Database creation options
46	 */
47	export interface DatabaseOptions {
48	  /** Preferred provider (auto = platform-aware selection) */
49	  provider?: DatabaseProvider;
50	
51	  /** Enable verbose logging */
52	  verbose?: boolean;
53	
54	  /** Enable WAL mode (better-sqlite3 only) */
55	  walMode?: boolean;
56	
57	  /** Enable query optimization */
58	  optimize?: boolean;
59	
60	  /** Default namespace */
61	  defaultNamespace?: string;
62	
63	  /** Maximum entries before auto-cleanup */
64	  maxEntries?: number;
65	
66	  /** Auto-persist interval for sql.js (milliseconds) */
67	  autoPersistInterval?: number;
68	
69	  /** Path to sql.js WASM file */
70	  wasmPath?: string;
71	
72	  /**
73	   * Embedding generator. Required for `'hybrid'` and `'agentdb'` providers
74	   * (and recommended for semantic search on any provider).
75	   */
