82	/**
83	 * Platform detection result
84	 */
85	interface PlatformInfo {
86	  os: string;
87	  isWindows: boolean;
88	  isMacOS: boolean;
89	  isLinux: boolean;
90	  recommendedProvider: DatabaseProvider;
91	}
