93	/**
94	 * Detect platform and recommend provider
95	 */
96	function detectPlatform(): PlatformInfo {
97	  const os = platform();
98	  const isWindows = os === 'win32';
99	  const isMacOS = os === 'darwin';
100	  const isLinux = os === 'linux';
101	
102	  // Recommend better-sqlite3 for Unix-like systems, sql.js for Windows
103	  const recommendedProvider: DatabaseProvider = isWindows ? 'sql.js' : 'better-sqlite3';
104	
105	  return {
106	    os,
107	    isWindows,
108	    isMacOS,
109	    isLinux,
110	    recommendedProvider,
111	  };
112	}
