135	/**
136	 * Test if sql.js is available and working
137	 */
138	async function testSqlJs(): Promise<boolean> {
139	  try {
140	    const initSqlJs = (await import('sql.js')).default;
141	    const SQL = await initSqlJs();
142	    const testDb = new SQL.Database();
143	    testDb.close();
