150	/**
151	 * Select best available provider
152	 */
153	async function selectProvider(
154	  preferred?: DatabaseProvider,
155	  verbose: boolean = false
156	): Promise<DatabaseProvider> {
157	  if (preferred && preferred !== 'auto') {
158	    if (verbose) {
159	      console.log(`[DatabaseProvider] Using explicitly specified provider: ${preferred}`);
160	    }
161	    return preferred;
162	  }
163	
164	  const platformInfo = detectPlatform();
165	
166	  if (verbose) {
167	    console.log(`[DatabaseProvider] Platform detected: ${platformInfo.os}`);
168	    console.log(`[DatabaseProvider] Recommended provider: ${platformInfo.recommendedProvider}`);
169	  }
170	
171	  // Try RVF first (always available via pure-TS fallback, native when @ruvector/rvf installed)
172	  if (await testRvf()) {
173	    if (verbose) {
174	      console.log('[DatabaseProvider] RVF backend available');
175	    }
176	    return 'rvf';
177	  }
178	
179	  // Try recommended provider
180	  if (platformInfo.recommendedProvider === 'better-sqlite3') {
181	    if (await testBetterSqlite3()) {
182	      if (verbose) {
183	        console.log('[DatabaseProvider] better-sqlite3 available and working');
184	      }
185	      return 'better-sqlite3';
186	    } else if (verbose) {
187	      console.log('[DatabaseProvider] better-sqlite3 not available, trying sql.js');
188	    }
189	  }
190	
191	  // Try sql.js as fallback
192	  if (await testSqlJs()) {
193	    if (verbose) {
194	      console.log('[DatabaseProvider] sql.js available and working');
195	    }
196	    return 'sql.js';
197	  } else if (verbose) {
198	    console.log('[DatabaseProvider] sql.js not available, using JSON fallback');
199	  }
200	
201	  // Final fallback to JSON
202	  return 'json';
203	}
