205	/**
206	 * Create a database instance with platform-aware provider selection
207	 *
208	 * @param path - Database file path (:memory: for in-memory)
209	 * @param options - Database configuration options
210	 * @returns Initialized database backend
211	 *
212	 * @example
213	 * ```typescript
214	 * // Auto-select best provider for platform
215	 * const db = await createDatabase('./data/memory.db');
216	 *
217	 * // Force specific provider
218	 * const db = await createDatabase('./data/memory.db', {
219	 *   provider: 'sql.js'
220	 * });
221	 *
222	 * // With custom options
223	 * const db = await createDatabase('./data/memory.db', {
224	 *   verbose: true,
225	 *   optimize: true,
226	 *   autoPersistInterval: 10000
227	 * });
228	 * ```
229	 */
230	export async function createDatabase(
231	  path: string,
232	  options: DatabaseOptions = {}
233	): Promise<IMemoryBackend> {
234	  const {
235	    provider = 'auto',
236	    verbose = false,
237	    walMode = true,
238	    optimize = true,
239	    defaultNamespace = 'default',
240	    maxEntries = 1000000,
241	    autoPersistInterval = 5000,
242	    wasmPath,
243	    embeddingGenerator,
244	    dimensions = 1536,
245	  } = options;
246	
247	  // Select provider
248	  const selectedProvider = await selectProvider(provider, verbose);
249	
250	  if (verbose) {
251	    console.log(`[DatabaseProvider] Creating database with provider: ${selectedProvider}`);
252	    console.log(`[DatabaseProvider] Database path: ${path}`);
253	  }
254	
255	  let backend: IMemoryBackend;
256	
257	  switch (selectedProvider) {
258	    case 'better-sqlite3': {
259	      const config: Partial<SQLiteBackendConfig> = {
260	        databasePath: path,
261	        walMode,
262	        optimize,
263	        defaultNamespace,
264	        maxEntries,
265	        verbose,
266	      };
267	
268	      backend = new SQLiteBackend(config);
269	      break;
270	    }
271	
272	    case 'sql.js': {
273	      const config: Partial<SqlJsBackendConfig> = {
274	        databasePath: path,
275	        optimize,
276	        defaultNamespace,
277	        maxEntries,
278	        verbose,
279	        autoPersistInterval,
280	        wasmPath,
281	      };
282	
283	      backend = new SqlJsBackend(config);
284	      break;
285	    }
286	
287	    case 'rvf': {
288	      const { RvfBackend } = await import('./rvf-backend.js');
289	      backend = new RvfBackend({
290	        databasePath: path.replace(/\.(db|json)$/, '.rvf'),
291	        dimensions,
292	        verbose,
293	        defaultNamespace,
294	        autoPersistInterval,
295	      });
296	      break;
297	    }
298	
299	    case 'hybrid': {
300	      // ADR-009: SQLite for structured queries + AgentDB for semantic search.
301	      const { HybridBackend } = await import('./hybrid-backend.js');
302	      backend = new HybridBackend({
303	        sqlite: {
304	          databasePath: path,
305	          walMode,
306	          optimize,
307	          defaultNamespace,
308	          maxEntries,
309	          verbose,
310	        },
311	        agentdb: {
312	          dbPath: path.replace(/\.(db|json|rvf)$/, '.agentdb'),
313	          namespace: defaultNamespace,
314	          vectorDimension: dimensions,
315	          embeddingGenerator,
316	          maxEntries,
317	        },
318	        defaultNamespace,
319	        embeddingGenerator,
320	      });
321	      break;
322	    }
323	
324	    case 'agentdb': {
325	      const { AgentDBBackend } = await import('./agentdb-backend.js');
326	      backend = new AgentDBBackend({
327	        dbPath: path,
328	        namespace: defaultNamespace,
329	        vectorDimension: dimensions,
330	        embeddingGenerator,
331	        maxEntries,
332	      });
333	      break;
334	    }
335	
336	    case 'json': {
337	      // Simple JSON file backend (minimal implementation)
338	      backend = new JsonBackend(path, verbose);
339	      break;
340	    }
341	
342	    default:
343	      throw new Error(`Unknown database provider: ${selectedProvider}`);
344	  }
345	
346	  // Initialize the backend
347	  await backend.initialize();
348	
349	  if (verbose) {
350	    console.log(`[DatabaseProvider] Database initialized successfully`);
351	  }
352	
353	  return backend;
354	}
