380	// ===== JSON Fallback Backend =====
381	
382	/**
383	 * Simple JSON file backend for when no SQLite is available
384	 */
385	class JsonBackend implements IMemoryBackend {
386	  private entries: Map<string, MemoryEntry> = new Map();
387	  private path: string;
388	  private verbose: boolean;
389	  private initialized: boolean = false;
390	
391	  constructor(path: string, verbose: boolean = false) {
392	    this.path = path;
393	    this.verbose = verbose;
394	  }
395	
396	  async initialize(): Promise<void> {
397	    if (this.initialized) return;
398	
399	    // Load from file if exists
400	    if (this.path !== ':memory:' && existsSync(this.path)) {
401	      try {
402	        const fs = await import('node:fs/promises');
403	        const data = await fs.readFile(this.path, 'utf-8');
404	        const entries = JSON.parse(data);
405	
406	        for (const entry of entries) {
407	          // Convert embedding array back to Float32Array
408	          if (entry.embedding) {
409	            entry.embedding = new Float32Array(entry.embedding);
410	          }
411	          this.entries.set(entry.id, entry);
412	        }
413	
414	        if (this.verbose) {
415	          console.log(`[JsonBackend] Loaded ${this.entries.size} entries from ${this.path}`);
416	        }
417	      } catch (error) {
418	        if (this.verbose) {
419	          console.error('[JsonBackend] Error loading file:', error);
420	        }
421	      }
422	    }
423	
424	    this.initialized = true;
425	  }
426	
427	  async shutdown(): Promise<void> {
428	    await this.persist();
429	    this.initialized = false;
430	  }
431	
432	  async store(entry: MemoryEntry): Promise<void> {
433	    this.entries.set(entry.id, entry);
434	    await this.persist();
435	  }
436	
437	  async get(id: string): Promise<MemoryEntry | null> {
438	    return this.entries.get(id) || null;
439	  }
440	
441	  async getByKey(namespace: string, key: string): Promise<MemoryEntry | null> {
442	    for (const entry of this.entries.values()) {
443	      if (entry.namespace === namespace && entry.key === key) {
444	        return entry;
445	      }
446	    }
447	    return null;
448	  }
449	
450	  async update(id: string, updateData: MemoryEntryUpdate): Promise<MemoryEntry | null> {
451	    const entry = this.entries.get(id);
452	    if (!entry) return null;
453	
454	    const updated = { ...entry, ...updateData, updatedAt: Date.now(), version: entry.version + 1 };
455	    this.entries.set(id, updated);
456	    await this.persist();
457	    return updated;
458	  }
459	
460	  async delete(id: string): Promise<boolean> {
461	    const result = this.entries.delete(id);
462	    await this.persist();
463	    return result;
464	  }
465	
466	  async query(query: MemoryQuery): Promise<MemoryEntry[]> {
467	    let results = Array.from(this.entries.values());
468	
469	    if (query.namespace) {
470	      results = results.filter((e) => e.namespace === query.namespace);
471	    }
472	
473	    if (query.key) {
474	      results = results.filter((e) => e.key === query.key);
475	    }
476	
477	    if (query.tags && query.tags.length > 0) {
478	      results = results.filter((e) => query.tags!.every((tag) => e.tags.includes(tag)));
479	    }
480	
481	    return results.slice(0, query.limit);
482	  }
483	
484	  async search(embedding: Float32Array, options: SearchOptions): Promise<SearchResult[]> {
485	    // Simple brute-force search
486	    const results: SearchResult[] = [];
487	
488	    for (const entry of this.entries.values()) {
489	      if (!entry.embedding) continue;
490	
491	      const similarity = this.cosineSimilarity(embedding, entry.embedding);
492	      if (options.threshold && similarity < options.threshold) continue;
493	
494	      results.push({ entry, score: similarity, distance: 1 - similarity });
495	    }
496	
497	    results.sort((a, b) => b.score - a.score);
498	    return results.slice(0, options.k);
499	  }
500	
501	  async bulkInsert(entries: MemoryEntry[]): Promise<void> {
502	    for (const entry of entries) {
503	      this.entries.set(entry.id, entry);
504	    }
505	    await this.persist();
506	  }
507	
508	  async bulkDelete(ids: string[]): Promise<number> {
509	    let count = 0;
510	    for (const id of ids) {
511	      if (this.entries.delete(id)) count++;
512	    }
513	    await this.persist();
514	    return count;
515	  }
516	
517	  async count(namespace?: string): Promise<number> {
518	    if (!namespace) return this.entries.size;
519	
520	    let count = 0;
521	    for (const entry of this.entries.values()) {
522	      if (entry.namespace === namespace) count++;
523	    }
524	    return count;
525	  }
526	
527	  async listNamespaces(): Promise<string[]> {
528	    const namespaces = new Set<string>();
529	    for (const entry of this.entries.values()) {
530	      namespaces.add(entry.namespace);
531	    }
532	    return Array.from(namespaces);
533	  }
534	
535	  async clearNamespace(namespace: string): Promise<number> {
536	    let count = 0;
537	    for (const [id, entry] of this.entries.entries()) {
538	      if (entry.namespace === namespace) {
539	        this.entries.delete(id);
540	        count++;
541	      }
542	    }
543	    await this.persist();
544	    return count;
545	  }
546	
547	  async getStats(): Promise<BackendStats> {
548	    return {
549	      totalEntries: this.entries.size,
550	      entriesByNamespace: {},
551	      entriesByType: {} as any,
552	      memoryUsage: 0,
553	      avgQueryTime: 0,
554	      avgSearchTime: 0,
555	    };
556	  }
557	
558	  async healthCheck(): Promise<HealthCheckResult> {
559	    return {
560	      status: 'healthy',
561	      components: {
562	        storage: { status: 'healthy', latency: 0 },
563	        index: { status: 'healthy', latency: 0 },
564	        cache: { status: 'healthy', latency: 0 },
565	      },
566	      timestamp: Date.now(),
567	      issues: [],
568	      recommendations: ['Consider using SQLite backend for better performance'],
569	    };
570	  }
571	
572	  private async persist(): Promise<void> {
573	    if (this.path === ':memory:') return;
574	
575	    const fs = await import('node:fs/promises');
576	    const entries = Array.from(this.entries.values()).map((e) => ({
577	      ...e,
578	      // Convert Float32Array to regular array for JSON serialization
579	      embedding: e.embedding ? Array.from(e.embedding) : undefined,
580	    }));
581	
582	    await fs.writeFile(this.path, JSON.stringify(entries, null, 2));
583	  }
584	
585	  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
586	    let dot = 0;
587	    let normA = 0;
588	    let normB = 0;
589	
590	    for (let i = 0; i < a.length; i++) {
591	      dot += a[i] * b[i];
592	      normA += a[i] * a[i];
593	      normB += b[i] * b[i];
594	    }
595	
596	    if (normA === 0 || normB === 0) return 0;
597	    return dot / (Math.sqrt(normA) * Math.sqrt(normB));
598	  }
599	}
