112	export class EventStore extends EventEmitter {
113	  private config: EventStoreConfig;
114	  private db: SqlJsDatabase | null = null;
115	  private initialized: boolean = false;
116	  private persistTimer: NodeJS.Timeout | null = null;
117	  private SQL: any = null;
118	
119	  // Version tracking per aggregate
120	  private aggregateVersions: Map<string, number> = new Map();
121	
122	  constructor(config: Partial<EventStoreConfig> = {}) {
123	    super();
124	    this.config = { ...DEFAULT_CONFIG, ...config };
125	  }
126	
127	  /**
128	   * Initialize the event store
129	   */
130	  async initialize(): Promise<void> {
131	    if (this.initialized) return;
132	
133	    // Load sql.js WASM
134	    let wasmLocator: ((file: string) => string) | undefined;
135	    if (this.config.wasmPath) {
136	      wasmLocator = () => this.config.wasmPath!;
137	    } else {
138	      try {
139	        const req = createRequire(import.meta.url);
140	        const sqlJsPath = req.resolve('sql.js/dist/sql-wasm.wasm');
141	        wasmLocator = () => sqlJsPath;
142	      } catch {
143	        wasmLocator = (file: string) => `https://sql.js.org/dist/${file}`;
144	      }
145	    }
146	    this.SQL = await initSqlJs({ locateFile: wasmLocator });
147	
148	    // Load existing database if exists
149	    if (this.config.databasePath !== ':memory:' && existsSync(this.config.databasePath)) {
150	      const buffer = readFileSync(this.config.databasePath);
151	      this.db = new this.SQL.Database(new Uint8Array(buffer));
152	
153	      if (this.config.verbose) {
154	        console.log(`[EventStore] Loaded database from ${this.config.databasePath}`);
155	      }
156	    } else {
157	      this.db = new this.SQL.Database();
158	
159	      if (this.config.verbose) {
160	        console.log('[EventStore] Created new event store database');
161	      }
162	    }
163	
164	    // Create schema
165	    this.createSchema();
166	
167	    // Load aggregate versions
168	    this.loadAggregateVersions();
169	
170	    // Set up auto-persist
171	    if (this.config.autoPersistInterval > 0 && this.config.databasePath !== ':memory:') {
172	      this.persistTimer = setInterval(() => {
173	        this.persist().catch((err) => {
174	          this.emit('error', { operation: 'auto-persist', error: err });
175	        });
176	      }, this.config.autoPersistInterval);
177	    }
178	
179	    this.initialized = true;
180	    this.emit('initialized');
181	  }
182	
183	  /**
184	   * Shutdown the event store
185	   */
186	  async shutdown(): Promise<void> {
187	    if (!this.initialized || !this.db) return;
188	
189	    // Stop auto-persist
190	    if (this.persistTimer) {
191	      clearInterval(this.persistTimer);
192	      this.persistTimer = null;
193	    }
194	
195	    // Final persist
196	    if (this.config.databasePath !== ':memory:') {
197	      await this.persist();
198	    }
199	
200	    this.db.close();
201	    this.db = null;
202	    this.initialized = false;
203	    this.emit('shutdown');
204	  }
205	
206	  /**
207	   * Append a new event to the store
208	   */
209	  async append(event: DomainEvent): Promise<void> {
210	    this.ensureInitialized();
211	
212	    // Get next version for aggregate
213	    const currentVersion = this.aggregateVersions.get(event.aggregateId) || 0;
214	    const nextVersion = currentVersion + 1;
215	
216	    // Set version on event
217	    event.version = nextVersion;
218	
219	    // Insert event
220	    const stmt = `
221	      INSERT INTO events (
222	        id, type, aggregate_id, aggregate_type, version, timestamp,
223	        source, payload, metadata, causation_id, correlation_id
224	      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
225	    `;
226	
227	    this.db!.run(stmt, [
228	      event.id,
229	      event.type,
230	      event.aggregateId,
231	      event.aggregateType,
232	      event.version,
233	      event.timestamp,
234	      event.source,
235	      JSON.stringify(event.payload),
236	      JSON.stringify(event.metadata || {}),
237	      event.causationId || null,
238	      event.correlationId || null,
239	    ]);
240	
241	    // Update version tracker
242	    this.aggregateVersions.set(event.aggregateId, nextVersion);
243	
244	    // Emit event appended notification
245	    this.emit('event:appended', event);
246	
247	    // Check if snapshot needed
248	    if (nextVersion % this.config.snapshotThreshold === 0) {
249	      this.emit('snapshot:recommended', { aggregateId: event.aggregateId, version: nextVersion });
250	    }
251	  }
252	
253	  /**
254	   * Get events for a specific aggregate
255	   */
256	  async getEvents(aggregateId: string, fromVersion?: number): Promise<DomainEvent[]> {
257	    this.ensureInitialized();
258	
259	    let sql = 'SELECT * FROM events WHERE aggregate_id = ?';
260	    const params: any[] = [aggregateId];
261	
262	    if (fromVersion !== undefined) {
263	      sql += ' AND version >= ?';
264	      params.push(fromVersion);
265	    }
266	
267	    sql += ' ORDER BY version ASC';
268	
269	    const stmt = this.db!.prepare(sql);
270	    const events: DomainEvent[] = [];
271	
272	    stmt.bind(params);
273	    while (stmt.step()) {
274	      const row = stmt.getAsObject();
275	      events.push(this.rowToEvent(row));
276	    }
277	
278	    stmt.free();
279	
280	    return events;
281	  }
