283	  /**
284	   * Get events by type
285	   */
286	  async getEventsByType(type: string): Promise<DomainEvent[]> {
287	    this.ensureInitialized();
288	
289	    const stmt = this.db!.prepare('SELECT * FROM events WHERE type = ? ORDER BY timestamp ASC');
290	    const events: DomainEvent[] = [];
291	
292	    stmt.bind([type]);
293	    while (stmt.step()) {
294	      const row = stmt.getAsObject();
295	      events.push(this.rowToEvent(row));
296	    }
297	
298	    stmt.free();
299	
300	    return events;
301	  }
302	
303	  /**
304	   * Query events with filters
305	   */
306	  async query(filter: EventFilter): Promise<DomainEvent[]> {
307	    this.ensureInitialized();
308	
309	    let sql = 'SELECT * FROM events WHERE 1=1';
310	    const params: any[] = [];
311	
312	    // Aggregate ID filter
313	    if (filter.aggregateIds && filter.aggregateIds.length > 0) {
314	      sql += ` AND aggregate_id IN (${filter.aggregateIds.map(() => '?').join(',')})`;
315	      params.push(...filter.aggregateIds);
316	    }
317	
318	    // Aggregate type filter
319	    if (filter.aggregateTypes && filter.aggregateTypes.length > 0) {
320	      sql += ` AND aggregate_type IN (${filter.aggregateTypes.map(() => '?').join(',')})`;
321	      params.push(...filter.aggregateTypes);
322	    }
323	
324	    // Event type filter
325	    if (filter.eventTypes && filter.eventTypes.length > 0) {
326	      sql += ` AND type IN (${filter.eventTypes.map(() => '?').join(',')})`;
327	      params.push(...filter.eventTypes);
328	    }
329	
330	    // Timestamp filters
331	    if (filter.afterTimestamp) {
332	      sql += ' AND timestamp > ?';
333	      params.push(filter.afterTimestamp);
334	    }
335	
336	    if (filter.beforeTimestamp) {
337	      sql += ' AND timestamp < ?';
338	      params.push(filter.beforeTimestamp);
339	    }
340	
341	    // Version filter
342	    if (filter.fromVersion) {
343	      sql += ' AND version >= ?';
344	      params.push(filter.fromVersion);
345	    }
346	
347	    // Order by timestamp
348	    sql += ' ORDER BY timestamp ASC';
349	
350	    // Pagination
351	    if (filter.limit) {
352	      sql += ' LIMIT ?';
353	      params.push(filter.limit);
354	    }
355	
356	    if (filter.offset) {
357	      sql += ' OFFSET ?';
358	      params.push(filter.offset);
359	    }
360	
361	    const stmt = this.db!.prepare(sql);
362	    const events: DomainEvent[] = [];
363	
364	    stmt.bind(params);
365	    while (stmt.step()) {
366	      const row = stmt.getAsObject();
367	      events.push(this.rowToEvent(row));
368	    }
369	
370	    stmt.free();
371	
372	    return events;
373	  }
374	
375	  /**
376	   * Replay events from a specific version
377	   */
378	  async *replay(fromVersion: number = 0): AsyncIterable<DomainEvent> {
379	    this.ensureInitialized();
380	
381	    const stmt = this.db!.prepare('SELECT * FROM events WHERE rowid >= ? ORDER BY rowid ASC');
382	    stmt.bind([fromVersion]);
383	
384	    while (stmt.step()) {
385	      const row = stmt.getAsObject();
386	      yield this.rowToEvent(row);
387	    }
388	
389	    stmt.free();
390	  }
