392	  /**
393	   * Save a snapshot for an aggregate
394	   */
395	  async saveSnapshot(snapshot: EventSnapshot): Promise<void> {
396	    this.ensureInitialized();
397	
398	    const stmt = `
399	      INSERT OR REPLACE INTO snapshots (
400	        aggregate_id, aggregate_type, version, state, timestamp
401	      ) VALUES (?, ?, ?, ?, ?)
402	    `;
403	
404	    this.db!.run(stmt, [
405	      snapshot.aggregateId,
406	      snapshot.aggregateType,
407	      snapshot.version,
408	      JSON.stringify(snapshot.state),
409	      snapshot.timestamp,
