415	  /**
416	   * Get snapshot for an aggregate
417	   */
418	  async getSnapshot(aggregateId: string): Promise<EventSnapshot | null> {
419	    this.ensureInitialized();
420	
421	    const stmt = this.db!.prepare(
422	      'SELECT * FROM snapshots WHERE aggregate_id = ? ORDER BY version DESC LIMIT 1'
423	    );
424	
425	    const row = stmt.getAsObject([aggregateId]);
426	    stmt.free();
427	
428	    if (!row || Object.keys(row).length === 0) {
429	      return null;
430	    }
431	
432	    return {
433	      aggregateId: row.aggregate_id as string,
434	      aggregateType: row.aggregate_type as any,
435	      version: row.version as number,
436	      state: JSON.parse(row.state as string),
437	      timestamp: row.timestamp as number,
438	    };
