441	  /**
442	   * Get event store statistics
443	   */
444	  async getStats(): Promise<EventStoreStats> {
445	    this.ensureInitialized();
446	
447	    // Total events
448	    const totalStmt = this.db!.prepare('SELECT COUNT(*) as count FROM events');
449	    const totalRow = totalStmt.getAsObject([]);
450	    totalStmt.free();
451	    const totalEvents = (totalRow.count as number) || 0;
452	
453	    // Events by type
454	    const typeStmt = this.db!.prepare('SELECT type, COUNT(*) as count FROM events GROUP BY type');
455	    const eventsByType: Record<string, number> = {};
456	    while (typeStmt.step()) {
457	      const row = typeStmt.getAsObject();
458	      eventsByType[row.type as string] = (row.count as number) || 0;
459	    }
460	    typeStmt.free();
461	
462	    // Events by aggregate
463	    const aggStmt = this.db!.prepare(
464	      'SELECT aggregate_id, COUNT(*) as count FROM events GROUP BY aggregate_id'
465	    );
466	    const eventsByAggregate: Record<string, number> = {};
467	    while (aggStmt.step()) {
468	      const row = aggStmt.getAsObject();
469	      eventsByAggregate[row.aggregate_id as string] = (row.count as number) || 0;
470	    }
471	    aggStmt.free();
472	
473	    // Timestamp range
474	    const rangeStmt = this.db!.prepare('SELECT MIN(timestamp) as oldest, MAX(timestamp) as newest FROM events');
475	    const rangeRow = rangeStmt.getAsObject([]);
476	    rangeStmt.free();
477	
478	    // Snapshot count
479	    const snapshotStmt = this.db!.prepare('SELECT COUNT(*) as count FROM snapshots');
480	    const snapshotRow = snapshotStmt.getAsObject([]);
481	    snapshotStmt.free();
482	
483	    return {
484	      totalEvents,
485	      eventsByType,
486	      eventsByAggregate,
487	      oldestEvent: (rangeRow.oldest as number) || null,
488	      newestEvent: (rangeRow.newest as number) || null,
489	      snapshotCount: (snapshotRow.count as number) || 0,
490	    };
491	  }
