493	  /**
494	   * Persist to disk
495	   */
496	  async persist(): Promise<void> {
497	    if (!this.db || this.config.databasePath === ':memory:') {
498	      return;
499	    }
500	
501	    const data = this.db.export();
502	    const buffer = Buffer.from(data);
503	
504	    writeFileSync(this.config.databasePath, buffer);
505	
506	    if (this.config.verbose) {
507	      console.log(`[EventStore] Persisted ${buffer.length} bytes to ${this.config.databasePath}`);
508	    }
509	
510	    this.emit('persisted', { size: buffer.length, path: this.config.databasePath });
511	  }
