513	  // ===== Private Methods =====
514	
515	  private createSchema(): void {
516	    if (!this.db) return;
517	
518	    // Events table
519	    this.db.run(`
520	      CREATE TABLE IF NOT EXISTS events (
521	        id TEXT PRIMARY KEY,
522	        type TEXT NOT NULL,
523	        aggregate_id TEXT NOT NULL,
524	        aggregate_type TEXT NOT NULL,
525	        version INTEGER NOT NULL,
526	        timestamp INTEGER NOT NULL,
527	        source TEXT NOT NULL,
528	        payload TEXT NOT NULL,
529	        metadata TEXT,
530	        causation_id TEXT,
531	        correlation_id TEXT
532	      )
533	    `);
534	
535	    // Indexes for performance
536	    this.db.run('CREATE INDEX IF NOT EXISTS idx_aggregate_id ON events(aggregate_id)');
537	    this.db.run('CREATE INDEX IF NOT EXISTS idx_aggregate_type ON events(aggregate_type)');
538	    this.db.run('CREATE INDEX IF NOT EXISTS idx_event_type ON events(type)');
539	    this.db.run('CREATE INDEX IF NOT EXISTS idx_timestamp ON events(timestamp)');
540	    this.db.run('CREATE INDEX IF NOT EXISTS idx_version ON events(version)');
541	    this.db.run(
542	      'CREATE UNIQUE INDEX IF NOT EXISTS idx_aggregate_version ON events(aggregate_id, version)'
543	    );
544	
545	    // Snapshots table
546	    this.db.run(`
547	      CREATE TABLE IF NOT EXISTS snapshots (
548	        aggregate_id TEXT PRIMARY KEY,
549	        aggregate_type TEXT NOT NULL,
550	        version INTEGER NOT NULL,
551	        state TEXT NOT NULL,
552	        timestamp INTEGER NOT NULL
553	      )
554	    `);
555	
556	    if (this.config.verbose) {
557	      console.log('[EventStore] Schema created successfully');
558	    }
559	  }
560	
561	  private loadAggregateVersions(): void {
562	    if (!this.db) return;
563	
564	    const stmt = this.db.prepare(
565	      'SELECT aggregate_id, MAX(version) as max_version FROM events GROUP BY aggregate_id'
566	    );
567	
568	    while (stmt.step()) {
569	      const row = stmt.getAsObject();
570	      this.aggregateVersions.set(row.aggregate_id as string, (row.max_version as number) || 0);
571	    }
572	
573	    stmt.free();
574	  }
575	
576	  private rowToEvent(row: any): DomainEvent {
577	    return {
578	      id: row.id as string,
579	      type: row.type as string,
580	      aggregateId: row.aggregate_id as string,
581	      aggregateType: row.aggregate_type as any,
582	      version: row.version as number,
583	      timestamp: row.timestamp as number,
584	      source: row.source as any,
585	      payload: JSON.parse(row.payload as string),
586	      metadata: row.metadata ? JSON.parse(row.metadata as string) : undefined,
587	      causationId: row.causation_id as string | undefined,
588	      correlationId: row.correlation_id as string | undefined,
589	    };
590	  }
591	
592	  private ensureInitialized(): void {
593	    if (!this.initialized || !this.db) {
594	      throw new Error('EventStore not initialized. Call initialize() first.');
595	    }
596	  }
597	}
