490	  /**
491	   * Initialize AgentDB instance with dynamic import and fallback chain.
492	   */
493	  private async initAgentDB(config: RuntimeConfig): Promise<void> {
494	    // Caller-supplied agentdb wins — used by tests (#2019 regression
495	    // guards) and by consumers that own the AgentDB lifecycle.
496	    if (config.agentdb) {
497	      this.agentdb = config.agentdb;
498	      this.emit('agentdb:initialized');
499	      return;
500	    }
501	
502	    try {
503	      // Validate dbPath to prevent path traversal
504	      const dbPath = config.dbPath || ':memory:';
505	      if (dbPath !== ':memory:') {
506	        // Use dynamic import instead of require() — require() is not defined in ESM
507	        // context and silently kills initAgentDB(), disabling all 15+ controllers (#1492).
508	        const { resolve: resolvePath } = await import('node:path');
509	        const resolved = resolvePath(dbPath);
510	        if (resolved.includes('..')) {
511	          this.emit('agentdb:unavailable', { reason: 'Invalid dbPath' });
512	          return;
513	        }
514	      }
515	
516	      const agentdbModule: any = await import('agentdb');
517	      const AgentDBClass = agentdbModule.AgentDB || agentdbModule.default;
518	
519	      if (!AgentDBClass) {
520	        this.emit('agentdb:unavailable', { reason: 'No AgentDB class found' });
521	        return;
522	      }
523	
524	      this.agentdb = new AgentDBClass({ dbPath });
525	
526	      // Suppress agentdb's noisy info-level output during init
527	      // using stderr redirect instead of monkey-patching console.log
528	      const origLog = console.log;
529	      const suppressFilter = (args: unknown[]) => {
530	        const msg = String(args[0] ?? '');
531	        return msg.includes('Transformers.js') ||
532	               msg.includes('better-sqlite3') ||
533	               msg.includes('[AgentDB]');
534	      };
535	      console.log = (...args: unknown[]) => {
536	        if (!suppressFilter(args)) origLog.apply(console, args);
537	      };
538	      try {
539	        await this.agentdb.initialize();
540	      } finally {
541	        console.log = origLog;
542	      }
543	      this.emit('agentdb:initialized');
544	    } catch (error) {
545	      const msg = error instanceof Error ? error.message : String(error);
546	      this.emit('agentdb:unavailable', { reason: msg.substring(0, 200) });
547	      this.agentdb = null;
548	    }
549	  }
