160	  /**
161	   * Store a memory entry
162	   */
163	  async store(entry: MemoryEntry): Promise<void> {
164	    this.ensureInitialized();
165	    const startTime = performance.now();
166	
167	    const stmt = this.db!.prepare(`
168	      INSERT OR REPLACE INTO memory_entries (
169	        id, key, content, type, namespace, tags, metadata,
170	        owner_id, access_level, created_at, updated_at, expires_at,
171	        version, "references", access_count, last_accessed_at
172	      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
173	    `);
174	
175	    stmt.run(
176	      entry.id,
177	      entry.key,
178	      entry.content,
179	      entry.type,
180	      entry.namespace,
181	      JSON.stringify(entry.tags),
182	      JSON.stringify(entry.metadata),
183	      entry.ownerId || null,
184	      entry.accessLevel,
185	      entry.createdAt,
186	      entry.updatedAt,
187	      entry.expiresAt || null,
188	      entry.version,
189	      JSON.stringify(entry.references),
190	      entry.accessCount,
191	      entry.lastAccessedAt
192	    );
193	
194	    // Store embedding separately (as BLOB)
195	    if (entry.embedding) {
196	      const embeddingStmt = this.db!.prepare(`
197	        INSERT OR REPLACE INTO memory_embeddings (entry_id, embedding)
198	        VALUES (?, ?)
199	      `);
200	      embeddingStmt.run(entry.id, Buffer.from(entry.embedding.buffer));
201	    }
202	
203	    // ADR-125 Phase 5 — mirror into FTS5 for keyword search.
204	    if (this.ftsAvailable) {
205	      // REPLACE semantics for FTS: delete-then-insert so updates reflect.
206	      this.db!.prepare('DELETE FROM memory_fts WHERE id = ?').run(entry.id);
207	      this.db!.prepare('INSERT INTO memory_fts(id, content) VALUES (?, ?)')
208	        .run(entry.id, entry.content);
209	    }
210	
211	    const duration = performance.now() - startTime;
212	    this.stats.writeCount++;
213	    this.stats.totalWriteTime += duration;
214	
215	    this.emit('entry:stored', { id: entry.id, duration });
216	  }
