301	  /**
302	   * ADR-125 Phase 5 — keyword (FTS5) search.
303	   *
304	   * Runs `memory_fts MATCH ?` ranked by FTS5's BM25 implementation, then
305	   * joins back to `memory_entries` for full records. Falls back to a
306	   * `LIKE`-based scan when FTS5 is unavailable.
307	   */
308	  async searchKeyword(query: string, limit: number = 10): Promise<SearchResult[]> {
309	    this.ensureInitialized();
310	    if (!query || !query.trim()) return [];
311	
312	    if (this.ftsAvailable) {
313	      try {
314	        const stmt = this.db!.prepare(`
315	          SELECT e.*, fts.rank as fts_rank
316	          FROM memory_fts AS fts
317	          JOIN memory_entries AS e ON e.id = fts.id
318	          WHERE memory_fts MATCH ?
319	          ORDER BY fts.rank
320	          LIMIT ?
321	        `);
322	        const rows = stmt.all(escapeFtsQuery(query), limit) as any[];
323	        return rows.map((row) => {
324	          const entry = this.rowToEntry(row);
325	          // FTS5 rank is non-positive — closer to 0 is better. Convert to
326	          // a [0,1] similarity-ish score so callers see a consistent shape.
327	          const score = 1 / (1 + Math.abs(row.fts_rank || 0));
328	          return { entry, score, distance: 1 - score };
329	        });
330	      } catch {
331	        // Fall through to LIKE
332	      }
333	    }
334	
335	    // LIKE fallback (does no ranking; first N matches)
336	    const like = `%${query.replace(/[%_]/g, '')}%`;
337	    const stmt = this.db!.prepare(
338	      'SELECT * FROM memory_entries WHERE content LIKE ? ORDER BY updated_at DESC LIMIT ?'
339	    );
340	    const rows = stmt.all(like, limit) as any[];
341	    return rows.map((row) => ({
342	      entry: this.rowToEntry(row),
343	      score: 0.5,
344	      distance: 0.5,
345	    }));
346	  }
