557	   * Get backend statistics
558	   */
559	  async getStats(): Promise<BackendStats> {
560	    this.ensureInitialized();
561	
562	    // Count by namespace
563	    const namespaceStmt = this.db!.prepare(`
564	      SELECT namespace, COUNT(*) as count
565	      FROM memory_entries
566	      GROUP BY namespace
567	    `);
568	    const namespaceRows = namespaceStmt.all() as any[];
569	    const entriesByNamespace: Record<string, number> = {};
570	    for (const row of namespaceRows) {
571	      entriesByNamespace[row.namespace] = row.count;
572	    }
573	
574	    // Count by type
575	    const typeStmt = this.db!.prepare(`
576	      SELECT type, COUNT(*) as count
577	      FROM memory_entries
578	      GROUP BY type
579	    `);
580	    const typeRows = typeStmt.all() as any[];
581	    const entriesByType: Record<MemoryType, number> = {
582	      episodic: 0,
583	      semantic: 0,
584	      procedural: 0,
585	      working: 0,
586	      cache: 0,
587	    };
588	    for (const row of typeRows) {
589	      entriesByType[row.type as MemoryType] = row.count;
590	    }
591	
592	    // Get database size
593	    const pageCount = this.db!.pragma('page_count', { simple: true }) as number;
594	    const pageSize = this.db!.pragma('page_size', { simple: true }) as number;
595	    const memoryUsage = pageCount * pageSize;
596	
597	    const totalEntries = await this.count();
598	
599	    return {
600	      totalEntries,
601	      entriesByNamespace,
602	      entriesByType,
603	      memoryUsage,
604	      avgQueryTime:
605	        this.stats.queryCount > 0
606	          ? this.stats.totalQueryTime / this.stats.queryCount
607	          : 0,
608	      avgSearchTime: 0, // Not applicable for SQLite
609	    };
610	  }
