612	  /**
613	   * Perform health check
614	   */
615	  async healthCheck(): Promise<HealthCheckResult> {
616	    const issues: string[] = [];
617	    const recommendations: string[] = [];
618	
619	    if (!this.initialized || !this.db) {
620	      return {
621	        status: 'unhealthy',
622	        components: {
623	          storage: { status: 'unhealthy', latency: 0, message: 'Not initialized' },
624	          index: { status: 'healthy', latency: 0 },
625	          cache: { status: 'healthy', latency: 0 },
626	        },
627	        timestamp: Date.now(),
628	        issues: ['Backend not initialized'],
629	        recommendations: ['Call initialize() before using'],
630	      };
631	    }
632	
633	    // Check database integrity
634	    let storageHealth: ComponentHealth;
635	    try {
636	      const integrityCheck = this.db.pragma('integrity_check', { simple: true });
637	      if (integrityCheck === 'ok') {
638	        storageHealth = { status: 'healthy', latency: 0 };
639	      } else {
640	        issues.push('Database integrity check failed');
641	        recommendations.push('Run VACUUM to repair database');
642	        storageHealth = { status: 'unhealthy', latency: 0, message: 'Integrity check failed' };
643	      }
644	    } catch (error) {
645	      issues.push('Failed to check database integrity');
646	      storageHealth = { status: 'unhealthy', latency: 0, message: String(error) };
647	    }
648	
649	    // Check utilization
650	    const totalEntries = await this.count();
651	    const utilizationPercent = (totalEntries / this.config.maxEntries) * 100;
652	
653	    if (utilizationPercent > 95) {
654	      issues.push('Storage utilization critical (>95%)');
655	      recommendations.push('Cleanup old data or increase maxEntries');
656	      storageHealth = { status: 'unhealthy', latency: 0, message: 'Near capacity' };
657	    } else if (utilizationPercent > 80) {
658	      issues.push('Storage utilization high (>80%)');
659	      recommendations.push('Consider cleanup');
660	      if (storageHealth.status === 'healthy') {
661	        storageHealth = { status: 'degraded', latency: 0, message: 'High utilization' };
662	      }
663	    }
664	
665	    const status =
666	      storageHealth.status === 'unhealthy'
667	        ? 'unhealthy'
668	        : storageHealth.status === 'degraded'
669	          ? 'degraded'
670	          : 'healthy';
671	
672	    return {
673	      status,
674	      components: {
675	        storage: storageHealth,
676	        index: { status: 'healthy', latency: 0 },
677	        cache: { status: 'healthy', latency: 0 },
678	      },
679	      timestamp: Date.now(),
680	      issues,
681	      recommendations,
682	    };
683	  }
