686	
687	  private ensureInitialized(): void {
688	    if (!this.initialized || !this.db) {
689	      throw new Error('SQLiteBackend not initialized. Call initialize() first.');
690	    }
691	  }
692	
693	  private createSchema(): void {
694	    if (!this.db) return;
695	
696	    // Main entries table
697	    this.db.exec(`
698	      CREATE TABLE IF NOT EXISTS memory_entries (
699	        id TEXT PRIMARY KEY,
700	        key TEXT NOT NULL,
701	        content TEXT NOT NULL,
702	        type TEXT NOT NULL,
703	        namespace TEXT NOT NULL,
704	        tags TEXT NOT NULL,
705	        metadata TEXT NOT NULL,
706	        owner_id TEXT,
707	        access_level TEXT NOT NULL,
708	        created_at INTEGER NOT NULL,
709	        updated_at INTEGER NOT NULL,
710	        expires_at INTEGER,
711	        version INTEGER NOT NULL,
712	        "references" TEXT NOT NULL,
713	        access_count INTEGER NOT NULL,
714	        last_accessed_at INTEGER NOT NULL
715	      );
716	
717	      CREATE INDEX IF NOT EXISTS idx_namespace ON memory_entries(namespace);
718	      CREATE INDEX IF NOT EXISTS idx_key ON memory_entries(key);
719	      CREATE INDEX IF NOT EXISTS idx_namespace_key ON memory_entries(namespace, key);
720	      CREATE INDEX IF NOT EXISTS idx_type ON memory_entries(type);
721	      CREATE INDEX IF NOT EXISTS idx_owner_id ON memory_entries(owner_id);
722	      CREATE INDEX IF NOT EXISTS idx_created_at ON memory_entries(created_at);
723	      CREATE INDEX IF NOT EXISTS idx_updated_at ON memory_entries(updated_at);
724	      CREATE INDEX IF NOT EXISTS idx_expires_at ON memory_entries(expires_at);
725	
726	      CREATE TABLE IF NOT EXISTS memory_embeddings (
727	        entry_id TEXT PRIMARY KEY,
728	        embedding BLOB,
729	        FOREIGN KEY (entry_id) REFERENCES memory_entries(id) ON DELETE CASCADE
730	      );
731	    `);
732	
733	    // ADR-125 Phase 5 — FTS5 virtual table for keyword search.
734	    // FTS5 is built into better-sqlite3 since 11.x. Surrounding try/catch so
735	    // older SQLite builds gracefully skip FTS without taking the whole backend
736	    // offline; queries against `searchKeyword` will fall back to LIKE.
737	    try {
738	      this.db.exec(`
739	        CREATE VIRTUAL TABLE IF NOT EXISTS memory_fts
740	          USING fts5(id UNINDEXED, content, tokenize='porter unicode61');
741	      `);
742	      this.ftsAvailable = true;
743	    } catch {
744	      this.ftsAvailable = false;
745	    }
746	  }
747	
748	  private rowToEntry(row: any): MemoryEntry {
749	    // Get embedding if exists
750	    let embedding: Float32Array | undefined;
751	    const embeddingStmt = this.db!.prepare(
752	      'SELECT embedding FROM memory_embeddings WHERE entry_id = ?'
753	    );
754	    const embeddingRow = embeddingStmt.get(row.id) as any;
755	    if (embeddingRow && embeddingRow.embedding) {
756	      embedding = new Float32Array(embeddingRow.embedding.buffer);
757	    }
758	
759	    return {
760	      id: row.id,
761	      key: row.key,
762	      content: row.content,
763	      embedding,
764	      type: row.type as MemoryType,
765	      namespace: row.namespace,
766	      tags: safeJsonParse<string[]>(row.tags || '[]'),
767	      metadata: safeJsonParse<Record<string, unknown>>(row.metadata || '{}'),
768	      ownerId: row.owner_id,
769	      accessLevel: row.access_level,
770	      createdAt: row.created_at,
771	      updatedAt: row.updated_at,
772	      expiresAt: row.expires_at,
773	      version: row.version,
774	      references: safeJsonParse<string[]>(row.references || '[]'),
775	      accessCount: row.access_count,
776	      lastAccessedAt: row.last_accessed_at,
777	    };
778	  }
