780	  /**
781	   * Synchronous store for use in transactions
782	   */
783	  private storeSync(entry: MemoryEntry): void {
784	    const stmt = this.db!.prepare(`
785	      INSERT OR REPLACE INTO memory_entries (
786	        id, key, content, type, namespace, tags, metadata,
787	        owner_id, access_level, created_at, updated_at, expires_at,
788	        version, "references", access_count, last_accessed_at
789	      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
790	    `);
791	
792	    stmt.run(
793	      entry.id,
794	      entry.key,
795	      entry.content,
796	      entry.type,
797	      entry.namespace,
798	      JSON.stringify(entry.tags),
799	      JSON.stringify(entry.metadata),
800	      entry.ownerId || null,
801	      entry.accessLevel,
802	      entry.createdAt,
803	      entry.updatedAt,
804	      entry.expiresAt || null,
805	      entry.version,
806	      JSON.stringify(entry.references),
807	      entry.accessCount,
808	      entry.lastAccessedAt
809	    );
